INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (403, 'Tom Holland', '1996-06-01', '\', 'Thomas "Tom" Stanley Holland is an English actor and dancer.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (404, 'Mark Wahlberg', '1971-06-05', '\', 'Mark Robert Michael Wahlberg (born June 5, 1971), former stage name Marky Mark, is an American actor, businessman, and former rapper. His work as a leading man spans the comedy, drama, and action genres. He has received multiple accolades, including a BAFTA Award, and nominations for two Academy Awards, three Golden Globe Awards, nine Primetime Emmy Awards, and three Screen Actors Guild Awards.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (368, 'Barry Keoghan', '1992-10-18', '\', 'Barry Keoghan (born 18 October 1992) is an Irish actor. He has appeared in the films Dunkirk; The Killing of a Sacred Deer, for which he won an Irish Film and Television Award for Best Supporting Actor and was nominated for the Independent Spirit Award for Best Supporting Male; and Calm with Horses, for which he was nominated for the BAFTA Award for Best Actor in a Supporting Role, and the RTÉ drama Love/Hate. He also played Druig in Eternals and the Joker in The Batman.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (369, 'Harry Styles', '1994-02-01', '\', 'Harry Edward Styles (born 1 February 1994) is an English singer and songwriter. His musical career began in 2010 as a solo contestant on the British music competition series The X Factor.  Styles has received various accolades, including six Brit Awards, three Grammy Awards, an Ivor Novello Award, and three American Music Awards. His film roles include Dunkirk (2017), Don''t Worry Darling, and My Policeman (both 2022). Aside from music and acting, Styles is known for his flamboyant fashion. He is the first man to appear solo on the cover of Vogue.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (370, 'Aneurin Barnard', '1987-05-08', '\', 'Aneurin Barnard (born 8 May 1987) is a Welsh television, stage and film actor. He is bilingual and has performed in both Welsh language and English language productions.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (371, 'Damien Bonnard', '1978-07-22', '\', 'Damien Bonnard was born on July 22, 1978 in Alès, Gard, France. He is an actor, known for Les Misérables (2019), Dunkirk (2017) and Staying Vertical (2016).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (372, 'Lee Armstrong', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (373, 'James Bloor', '1998-05-02', '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (374, 'Tom Glynn-Carney', '1995-02-07', '\', 'Tom Glynn-Carney (born February 7, 1995) is an English film, theatre and television actor. After studying at the Canon Slade School in Bolton he went on to study Musical Theatre in Pendleton College of Performing Arts and later attended the Guildhall School of Music and Drama in London where he studied acting.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (375, 'Jack Lowden', '1990-06-02', '\', 'Jack Andrew Lowden (born 2 June 1990) is a Scottish actor. Following a four-year stage career, his first major international onscreen success was in the 2016 BBC miniseries War & Peace, which led to starring roles in feature films. His most recent project is that of portraying Siegfried Sassoon in the 2022 biopic Benediction.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (376, 'Luke Thompson', '1988-07-04', '\', 'Luke Thompson (born 4 July 1988) is an English actor. He is best known for his role as Benedict, the second Bridgerton child, in the Netflix period drama Bridgerton (2020–present).
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (377, 'Michel Biel', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (378, 'Constantin Balsan', NULL, '\x6e756c6c', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (394, 'Matt Damon', '1970-10-08', '\', 'Matthew Paige Damon (born October 8, 1970) is an American actor, film producer, and screenwriter. He is the recipient of various accolades, including an Academy Award from five nominations, and two Golden Globe Awards. He also received three BAFTA Award nominations, seven Primetime Emmy Award nominations, and six Screen Actors Guild Awards.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (405, 'Sophia Ali', '1995-11-07', '\', 'Sophia Taylor Ramseyer Ali (born November 7, 1995) is an American actress. She is best known for her work in the MTV romantic comedy series, Faking It, the ABC medical drama series Grey''s Anatomy, and The Wilds.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (406, 'Tati Gabrielle', '1996-01-25', '\', 'Tatiana Gabrielle Hobson (born January 25, 1996) is an American actress. She is known for her roles as Gaia on The CW science fiction television series The 100, Prudence on the Netflix original series Chilling Adventures of Sabrina, Marienne Bellamy on the Netflix series You, and for providing the voice of Willow Park on the Disney animated series The Owl House.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (407, 'Antonio Banderas', '1960-08-10', '\', 'José Antonio Domínguez Bandera (born August 10, 1960), known professionally as Antonio Banderas, is a Spanish actor and singer. Known for his work in films of several genres, he has received various accolades, including a Cannes Film Festival Award and a European Film Award, in addition to nominations for an Academy Award, a Tony Award, two Primetime Emmy Awards, and five Golden Globe Awards.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (408, 'Steven Waddington', '1967-12-30', '\', 'Steven Waddington is an English film and television actor. He studied at the East 15 Acting School in Loughton, Essex and subsequently joined the Royal Shakespeare Company, first at Stratford and then at the Barbican, London.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (409, 'Rudy Pankow', '1998-08-12', '\', 'Rudy Pankow is an American film and television actor. He is most known for his role as JJ Maybank on the Netflix teen drama series Outer Banks.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (410, 'Tiernan Jones', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (411, 'Pingi Moli', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (412, 'Jesús Evita', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (413, 'Georgia Goodman', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (414, 'Diarmaid Murtagh', NULL, '\', 'Diarmaid Murtagh is an actor.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (415, 'Joseph Balderrama', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (416, 'Serena Posadino', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (417, 'Alana Boden', '1997-01-14', '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (418, 'Jonathan Failla', '1961-01-01', '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (419, 'Anthony Thomas', NULL, '\', 'Anthony Thomas is an American actor based in New York.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (420, 'Peter Seaton-Clark', '1972-07-29', '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (421, 'Robert Maaser', '1990-07-19', '\', 'Maaser was born in Strausberg, Germany, to Silvia and Thomas Maaser, a former MiG-29 pilot. He started artistic gymnastics at the age of 3. Six years later he started martial arts and wheel gymnastics. Until today he is the most successful competitor in the history of the sport with 14 world champion titles, 2 world cup wins and more than 50 national titles as well as the title as the youngest ever world champion at age 14.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (422, 'Eskindir Tesfay', '1976-10-13', '\x6e756c6c', 'Eskindir Tesfay is an Afro-German actor from Berlin, Germany, who is fluent in 4 languages. While living in Taiwan between 1999 and 2005, he intensely studied Chinese and martial arts, and gained first experiences as a model and actor for tv commercials. His knowledge of martial arts and fight choreography also qualified him for corresponding roles.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (423, 'Joaquin Phoenix', '1974-10-28', '\', 'Joaquin Rafael Phoenix (born October 28, 1974) is an American actor, producer, and animal rights activist. Known for playing dark and unconventional characters in independent film, he is the recipient of various accolades, including an Academy Award, a British Academy Film Award, a Grammy Award, and two Golden Globe Awards. In 2020, he was ranked 12th on the list of the 25 Greatest Actors of the 21st Century by The New York Times.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (424, 'Robert De Niro', '1943-08-17', '\', 'Robert Anthony De Niro (born August 17, 1943) is an American actor. Known for his collaborations with Martin Scorsese, he is considered to be one of the best actors of his generation. De Niro is the recipient of various accolades, including two Academy Awards, a Golden Globe Award, the Cecil B. DeMille Award, and a Screen Actors Guild Life Achievement Award. In 2009, De Niro received the Kennedy Center Honor, and earned a Presidential Medal of Freedom from U.S. President Barack Obama in 2016.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (425, 'Zazie Beetz', '1991-06-01', '\', 'Zazie Olivia Beetz (born June 1, 1991) is a German-American actress. She stars in the FX comedy-drama series Atlanta (2016–2022), for which she received a nomination for the Primetime Emmy Award for Outstanding Supporting Actress in a Comedy Series. She also appeared in the Netflix anthology series Easy (2016–19) and voices Amber Bennett in Amazon''s animated superhero action series Invincible.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (426, 'Frances Conroy', '1953-03-15', '\', 'Frances Conroy (born November 13, 1953) is an American actress. She is most widely known for playing the matriarch Ruth O''Connor Fisher Sibley on the HBO funeral drama series Six Feet Under, which earned her a Golden Globe in 2004.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (230, 'Leonardo DiCaprio', '1974-11-11', '\', 'Leonardo Wilhelm DiCaprio (born November 11, 1974) is an American actor and film producer. Known for his work in biopics and period films, DiCaprio is the recipient of numerous accolades, including an Academy Award, a British Academy Film Award, and three Golden Globe Awards. As of 2019, his films have grossed over $7.2 billion worldwide, and he has been placed eight times in annual rankings of the world''s highest-paid actors.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (231, 'Joseph Gordon-Levitt', '1981-02-17', '\', 'Joseph Leonard Gordon-Levitt (born February 17, 1981) is an American actor and filmmaker. He has received various accolades, including nominations for the Golden Globe Award for Best Actor – Motion Picture Musical or Comedy for his leading performances in 500 Days of Summer (2009) and 50/50 (2011). He is the founder of the online media platform HitRecord whose projects such as HitRecord on TV (2014–15) and Create Together (2020) won him two Primetime Emmy Awards in the category of Outstanding Interactive Program.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (427, 'Brett Cullen', '1956-08-26', '\', 'Peter Brett Cullen (born August 26, 1956) is an American actor who has appeared in numerous motion pictures and television programs. Early in 2007, he was cast as the role of an estranged father to one of the American football players, Tim Riggins (played by actor Taylor Kitsch), in the NBC drama series Friday Night Lights.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (428, 'Shea Whigham', '1969-01-05', '\', 'Franklin Shea Whigham Jr. (born January 5, 1969) is an American actor. He portrayed Elias "Eli" Thompson in the HBO drama series Boardwalk Empire, and had notable supporting roles in films Kong: Skull Island, Death Note, Take Shelter, and the first season of True Detective, the third season of Fargo, and Joker. He appeared as Agent Michael Stasiak in Fast & Furious and Fast & Furious 6.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (429, 'Bill Camp', '1964-10-13', '\', 'Bill Camp (born October 13, 1964) is an American actor, he played supporting roles in many films. He is best known for playing Detective Dennis Box in the HBO limited television series The Night Of, for which he was nominated for the Primetime Emmy Award for Outstanding Supporting Actor in a Limited Series or Movie.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (430, 'Glenn Fleshler', '1968-09-05', '\', 'Glenn Fleshler is an American theater, television, and film actor. Fleshler was born to a Jewish family and studied acting at New York University''s Tisch School of the Performing Arts, from which he has an MFA. He is known for his work on the shows True Detective, Billions and Boardwalk Empire.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (431, 'Leigh Gill', NULL, '\', 'Leigh Gill is known for Joker (2019), Fantastic Beasts and Where to Find Them (2016) and Game of Thrones (2011).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (432, 'Josh Pais', '1964-06-21', '\', 'Josh Pais (born June 21, 1964) is an American actor of film and television.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (433, 'Rocco Luna', NULL, '\x6e756c6c', 'Rocco Luna is known for Joker (2019) and Social Distance (2020).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (434, 'Marc Maron', '1963-09-27', '\', 'Marc Maron (born September 27, 1963) is an American stand-up comedian and podcast host.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (435, 'Sondra James', '1939-07-21', '\', 'Sondra James (July 21, 1939 - September 12, 2021) was an American sound coordinator and actress. She appeared in films such as the Oscar-winning film Joker (2019), Emma Seligman''s directorial debut Shiva Baby (2020), and a very small role in Spider-Man: Homecoming (2017). She also did ADR voice casting for multiple films such as Wes Anderson''s The Royal Tenenbaums (2001) and Mike Nichols'' Closer (2004).
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (234, 'Ken Watanabe', '1959-10-21', '\', 'Ken Watanabe (born October 21, 1959) is a Japanese stage, film, and television actor. To English-speaking audiences he is known for playing tragic hero characters, such as General Tadamichi Kuribayashi in Letters from Iwo Jima and Lord Katsumoto Moritsugu in The Last Samurai, for which he was nominated for the Academy Award for Best Supporting Actor. Among other awards, he has won the Japan Academy Prize for Best Actor twice, in 2007 for Memories of Tomorrow and in 2010 for Shizumanu Taiyō. He is also known for his roles in director Christopher Nolan''s Hollywood blockbusters Batman Begins and Inception.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (235, 'Tom Hardy', '1977-09-15', '\', 'Edward Thomas Hardy CBE (born 15 September 1977) is an English actor, producer, writer and former model. After studying acting at the Drama Centre London, he made his film debut in Ridley Scott''s Black Hawk Down (2001). He has since been nominated for the Academy Award for Best Supporting Actor, two Critics'' Choice Movie Awards and two British Academy Film Awards, receiving the 2011 BAFTA Rising Star Award.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (236, 'Elliot Page', '1987-02-21', '\', 'Elliot Page (born February 21, 1987) is a Canadian actor and producer.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (436, 'Murphy Guyer', '1952-12-25', '\', 'Murphy Guyer (born December 25, 1952) is an American actor, playwright, writer and director, best known for his plays and for appearances in the films The Devil''s Advocate (1997), The Jackal (1997), Arthur (2011) and Joker (2019).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (437, 'Douglas Hodge', '1960-02-25', '\', 'Douglas Hodge is an English actor, director, and musician who trained for the stage at the Royal Academy of Dramatic Art. Hodge is a council member of the National Youth Theatre for which, in 1989, he co-wrote Pacha Mama''s Blessing about the Amazon rain forests staged at the Almeida Theatre.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (438, 'Dante Pereira-Olson', '2008-08-13', '\', 'Dante Pereira-Olson is an actor.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (439, 'Carrie Louise Putrello', NULL, '\', 'Carrie Louise Putrello is known for Joker (2019), The Ultimate Playlist of Noise (2021) and Just for Showmance.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (440, 'Sharon Washington', NULL, '\', 'Sharon Washington is an American stage, TV, film, and voice actress. She received her MFA from the Yale School of Drama and her BA from Dartmouth College.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (441, 'Hannah Gross', '1992-09-25', '\', 'Hannah Gross is a Canadian actress, known for her roles in Mindhunter (2017), Joker (2019), and Colewell (2019).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (442, 'Frank Wood', '1960-05-06', '\', 'Frank Wood was born in 1960 in the USA. He is an actor, known for Joker (2019), Michael Clayton (2007) and Thirteen Days (2000).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (482, 'Barry Rothbart', '1983-05-25', '\', 'Barry Rothbart (born May 25, 1983) is an American comedian, actor and writer. He currently splits his time between Los Angeles and New York City. He was named one of Variety magazine''s "10 Comics to Watch" in 2013. He played the role of Peter Deblasio in 2013''s The Wolf of Wall Street , played Kevin on ABC''s Downward Dog and currently appears on Showtime''s Kidding.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (498, 'Patrick Fugit', '1982-10-27', '\', 'Patrick Raymond Fugit (born October 27, 1982) is an American actor best known for his performance in the lead role of Cameron Crowe''s film Almost Famous (2000). Since then, he has also appeared in the films White Oleander (2002), Spun (2003), Saved! (2004), Wristcutters: A Love Story (2006), We Bought a Zoo (2011) and Babylon (2022). Fugit also portrayed Kyle Barnes in the Cinemax series Outcast.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (237, 'Dileep Rao', '1973-07-29', '\', 'Dileep Rao (born July 29, 1973) is an American actor who has appeared in feature films and television series. He starred in Sam Raimi''s horror film Drag Me to Hell (2009), James Cameron''s science fiction film Avatar (2009), and Christopher Nolan''s thriller Inception (2010).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (238, 'Cillian Murphy', '1976-05-25', '\', 'Cillian Murphy (born 25 May 1976) is an Irish actor.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (239, 'Tom Berenger', '1949-05-31', '\', 'Tom Berenger is an American television and motion picture actor. He was nominated for the Academy Award for Best Supporting Actor for his portrayal of Staff Sergeant Bob Barnes in Platoon. He is also known for playing Jake Taylor in the Major League films and Thomas Beckett in the Sniper films.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (240, 'Marion Cotillard', '1975-09-30', '\', 'Marion Cotillard (born September 30, 1975) is a French actress, film producer, singer, songwriter, and environmentalist. Known for her roles in independent films and blockbusters, she has received various accolades, including an Academy Award, a British Academy Film Award, a Golden Globe Award, a European Film Award, a Lumières Award, and two César Awards. She became a Knight of the Order of Arts and Letters in France in 2010, and was promoted to Officer in 2016. She has served as a spokeswoman for Greenpeace since 2001. Cotillard was the face of the Lady Dior handbag for nine years. Since 2020, she is the face of Chanel''s fragrance Chanel No. 5.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (241, 'Pete Postlethwaite', '1946-02-07', '\', 'Pete Postlethwaite (February 7, 1946 - January 2, 2011) was an English stage, film and television actor. After minor television appearances including in The Professionals, Postlethwaite''s first success came with the film Distant Voices, Still Lives in 1988. He played a mysterious lawyer, Mr. Kobayashi, in The Usual Suspects, and he appeared in Alien 3, In the Name of the Father, Amistad, Brassed Off, The Shipping News, The Constant Gardener, The Age of Stupid, Inception, The Town, Romeo + Juliet, and Æon Flux. In television, Postlethwaite''s most notable performance was as the villain Sergeant Obadiah Hakeswill in the Sharpe television series and television movies opposite actor Sean Bean''s character of Richard Sharpe. Postlethwaite was born in Warrington, England in 1946. He trained as a teacher and taught drama before training as an actor. Steven Spielberg called Postlethwaite "the best actor in the world" after working with him on The Lost World: Jurassic Park. He received an Academy Award nomination for his role in In the Name of the Father in 1993, and was made an Officer of the Order of the British Empire in the 2004 New Year''s Honours List. He died of pancreatic cancer.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (242, 'Michael Caine', '1933-03-14', '\', 'Sir Michael Caine CBE (born Maurice Joseph Micklewhite Jr.; March 14, 1933) is a retired English actor. Known for his distinctive South London accent, he has appeared in more than 160 films in a career spanning seven decades, and is considered a British film icon. As of February 2017, the films in which Caine has appeared have grossed over $7.8 billion worldwide.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (243, 'Lukas Haas', '1976-04-16', '\', '​From Wikipedia, the free encyclopedia.  
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (244, 'Talulah Riley', '1985-09-26', '\', 'Talulah Riley is a British stage, film and television actress and novelist, best known for playing recurring character Angela on the HBO television series _Westworld_.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (245, 'Tohoru Masamune', '1959-11-18', '\', 'Born in Madison, Wisconsin, Tohoru grew up in Edmonton, Alberta, Canada. His parents emigrated together from Japan where his ancestors include Japanese novelist/playwright Hakucho Masamune. In 4th grade, Tohoru wrote and performed in his first play - He doesn''t remember too much of it, but does seem to recall it being somewhat of a hit at his elementary school! His immediate family eventually settled in Newton (suburb of Boston), Massachusetts, and Noank, Connecticut.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (246, 'Taylor Geare', '2001-09-19', '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (443, 'Ryan Gosling', '1980-11-12', '\', 'Ryan Thomas Gosling (born November 12, 1980) is a Canadian actor. Prominent in independent film, he has also worked in blockbuster films of varying genres, and has accrued a worldwide box office gross of over 1.9 billion USD. He has received various accolades, including a Golden Globe Award, and nominations for two Academy Awards and a BAFTA Award.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (444, 'Russell Crowe', '1964-04-07', '\', 'Russell Ira Crowe (born 7 April 1964) is an Academy Award-winning actor. He was born in New Zealand, spent ten years of his childhood in Australia, and moved there permanently at age 21. He came to international attention for his role as Roman General Maximus Decimus Meridius in the epic historical film Gladiator (2000), for which he won an Academy Award, Broadcast Film Critics Association Award, Empire Award, and London Film Critics Circle Award for Best Leading Actor, along with 10 other nominations in the same category.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (445, 'Angourie Rice', '2001-01-01', '\', 'Angourie Rice (/æŋˈɡaʊri/; born January 1, 2001) is an Australian actress. She began her career as a child actress, coming to attention for her roles in These Final Hours and The Nice Guys. She is known for her portrayal of Betty Brant in the Marvel Cinematic Universe, appearing in Spider-Man: Homecoming (2017), Spider-Man: Far From Home (2019), and Spider-Man: No Way Home (2021). She also has appearing roles in Senior Year (2022) & the broadway adaptation of Mean Girls (2024).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (446, 'Margaret Qualley', '1994-10-23', '\', 'Sarah Margaret Qualley (born October 23, 1994) is an American actress. The daughter of actress Andie MacDowell, she trained as a ballerina in her youth and briefly pursued a career in modeling. She made her acting debut with a minor role in the 2013 drama film Palo Alto and gained recognition for playing a troubled teenager in the HBO drama series The Leftovers (2014–2017). Qualley then appeared in the dark comedy The Nice Guys (2016) and in Netflix''s supernatural thriller Death Note (2017).
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (447, 'Matt Bomer', '1977-10-11', '\', 'Matthew Staton Bomer (born October 11, 1977) is an American actor. He is the recipient of accolades such as a Golden Globe Award, a Critics'' Choice Television Award, and a Primetime Emmy Award nomination.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (448, 'Beau Knapp', '1988-04-17', '\', 'Beau Christian Knapp (born April 17, 1989) is an American actor. He is known for his roles in The Signal (2014), Run All Night (2015), and Southpaw (2015). Knapp portrayed a lead villain in Death Wish (2018), the sixth installment of the Death Wish series. In 2021, he starred in the TV series adaptation of The Lost Symbol.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (395, 'Topher Grace', '1978-07-12', '\', 'Christopher John "Topher" Grace (born July 12, 1978) is an American actor. He is best known for his portrayal of Eric Forman on the FOX sitcom That ''70s Show, Eddie Brock/Venom in the Sam Raimi film Spider-Man 3, and Edwin in the 2010 film Predators.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (396, 'Timothée Chalamet', '1995-12-27', '\', 'Timothée Hal Chalamet (born December 27, 1995) is an American actor.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (499, 'Eric Roberts', '1956-04-18', '\', 'An American actor. His career began with a well-received performance in King of the Gypsies (1978), for which he earned his first Golden Globe Award nomination. His second Golden Globe nomination came for his portrayal of Paul Snider in Star 80 (1983), followed by Globe and Academy Award nominations for his supporting role in Runaway Train (1985). In a career spanning almost forty years, Roberts has performed in over 200 films, including Raggedy Man (1981), The Pope of Greenwich Village (1984), The Specialist (1994), Cecil B. Demented (2000), National Security (2003), The Dark Knight (2008), The Expendables (2010) and Inherent Vice (2014). His equally varied television work includes three seasons with the sitcom Less than Perfect, as well as recurring roles on the NBC drama Heroes and the CBS soap opera The Young and the Restless. His sisters Julia Roberts and Lisa Roberts Gillan, and daughter Emma Roberts, also have acting careers.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (449, 'Keith David', '1956-06-04', '\', 'Keith David (born June 4, 1956) is an American film, television, and voice actor, and singer. He is perhaps most known for his live-action roles in such films as Crash, There''s Something About Mary, Barbershop and Men at Work. He has also had memorable roles in numerous cult favorites, including John Carpenter''s films The Thing (as Childs) and They Live (as Armitage), the Riddick films Pitch Black and The Chronicles of Riddick (as the Imam), the General in Armageddon, King in Oliver Stone''s Platoon, and Big Tim in Darren Aronofsky''s Requiem for a Dream. David is also well known for his voice over career, primarily his Emmy winning work as the narrator of numerous Ken Burns films. Characters that he has voiced include Goliath on the Disney series Gargoyles, the Arbiter in Halo 2 and Halo 3, David Anderson in Mass Effect and Mass Effect 2, the Decepticon Barricade in Transformers: The Game, Julius Little in Saints Row and Saints Row 2, Sgt. Foley in Call of Duty: Modern Warfare 2, Dr. Facilier in The Princess and the Frog, and Chaos in Dissidia: Final Fantasy and Dissidia 012 Final Fantasy.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (450, 'Yaya DaCosta', '1982-11-15', '\', 'Camara DaCosta Johnson, professionally known as Yaya Alafia (formerly Yaya DaCosta), is an American actress and model. She''s best known for her starring role as April Sexton on NBC''s Chicago Med, as Andrea Vaughn in Our Kind of People, and as Whitney Houston in the TV movie Whitney.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (451, 'Kim Basinger', '1953-12-08', '\', 'Kimila Ann Basinger (born December 8, 1953) is an American actress and former fashion model. She has garnered acclaim for her work in film and television, for which she has received various accolades including an Academy Award, a Golden Globe Award, a Screen Actors Guild Award, and a star on the Hollywood Walk of Fame.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (452, 'Lois Smith', '1930-11-03', '\', 'Lois Arlene Smith (née Humbert; born November 3, 1930) is an American actress. She made her film debut in the 1955 drama film East of Eden, and later played supporting roles in a number of movies, including Five Easy Pieces (1970), Resurrection (1980), Fatal Attraction (1987), Fried Green Tomatoes (1991), How to Make an American Quilt (1995), Dead Man Walking, Twister (1996), Minority Report (2002), The Nice Guys (2016) and Lady Bird (2017).
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (453, 'Murielle Telio', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (454, 'Gil Gerard', '1943-01-23', '\', 'Gilbert C. Gerard is an American actor, most notable for his role as Captain William "Buck" Rogers in the 1979–81 television series Buck Rogers in the 25th Century.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (455, 'Daisy Tahan', '2001-03-25', '\', 'Daisy Tahan is an American actress best known for her role as Samantha Focker in Little Fockers. Tahan also originated the role of Fiona Peyton in the Showtime series Nurse Jackie. Daisy, the younger sister of actor Charlie Tahan, lives in Glen Rock, New Jersey.[1]');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (456, 'Jack Kilmer', '1995-06-06', '\', 'John Wallace "Jack" Kilmer (born June 6, 1995) is an American actor known for starring in the 2013 film Palo Alto and for playing Pelle "Dead" Ohlin in the 2018 Norwegian black metal biopic Lords of Chaos, and for playing Ozzy Osbourne in Ozzy''s "Under the Graveyard" video. He is also the narrator of Val, a documentary about his father Val Kilmer.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (457, 'Lance Valentine Butler', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (458, 'Ty Simpkins', '2001-08-06', '\', 'Ty Keegan Simpkins (born August 6, 2001) is an American actor. His notable film credits include the supernatural horror Insidious (2011), its sequel Insidious: Chapter 2 (2013) and Jurassic World (2015). He is also known for his appearances in the Marvel Cinematic Universe as Harley Keener in Iron Man 3 (2013) and Avengers: Endgame (2019).
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (459, 'Cayla Brady', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (460, 'Tammi Arender', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (397, 'David Oyelowo', '1976-04-01', '\', 'David Oyelowo (born April 1, 1976) is an English actor, director and producer. His family originates from Nigeria. David studied Theatre Studies for A level and his teacher suggested he should become an actor. After A levels David enrolled for a year on an Art foundation course. In December 2000 David became the first black actor to play an English monarch for the RSC taking the title role in Henry VI. His performance won him the ''Ian Charleson'' Award 2001 for best newcomer in a classical play.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (461, 'Rebecca Dalton Rusk', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (500, 'Cici Lau', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (501, 'Tyler Seiple', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (462, 'Terence Rosemore', '1964-07-29', '\', 'Terence Rosemore was born in Great Falls, Montana and raised in New Orleans where he got his start as an Actor in Ted Gilliam''s Dashiki Theatre Company.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (483, 'Brad Pitt', '1963-12-18', '\', 'William Bradley Pitt (born December 18, 1963) is an American actor and film producer. He is the recipient of various accolades, including an Academy Award, a British Academy Film Award, and two Golden Globe Awards for his acting, in addition to a second Academy Award, a second British Academy Film Award, a third Golden Globe Award, and a Primetime Emmy Award as a producer under his production company, Plan B Entertainment.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (485, 'Diego Calva', '1992-03-16', '\', 'Diego Calva Hernández (born March 16, 1992) is a Mexican actor best known for starring in the crime drama television series Narcos: Mexico (2021) and the comedy drama film Babylon (2022). For the latter, he received a nomination for the Golden Globe Award for Best Actor – Motion Picture Musical or Comedy.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (486, 'Jean Smart', '1951-09-13', '\', 'Jean Smart is an Emmy-Award Winning American stage, film and television actress, best known for her starring roles in Hacks and Designing Women. After beginning her career in regional theater in the Pacific Northwest, she appeared on Broadway in 1981 as Marlene Dietrich in the biographical play Piaf. Smart was later cast in a leading role as Charlene Frazier Stillfield on the CBS sitcom Designing Women, in which she starred from 1986 to 1991.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (263, 'Claire Geare', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (487, 'Flea', '1962-10-16', '\', 'Michael Peter Balzary (born October 16, 1962), known professionally as Flea, is an Australian-American musician and actor. He is a founding member and bassist of the rock band Red Hot Chili Peppers.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (488, 'Jovan Adepo', '1988-09-06', '\', 'Jovan Adepo (born September 6, 1988) is a British-born American actor. He is known for his role as Cory Maxson in the film adaptation of Fences (2016), and also had starring roles in the 2018 film Overlord and as Lionel Jefferson in CBS'' All in the Family/The Jeffersons special. Adepo was featured in the series When They See Us, the second season of Prime Video’s Jack Ryan, and the Facebook series Sorry for Your Loss. He plays Michael Murphy in the HBO series The Leftovers and in 2019 appeared in Watchmen as Hooded Justice. For the latter, he was nominated for the Primetime Emmy Award for Outstanding Supporting Actor in a Limited Series or Movie. He also starred as Larry Underwood in the Paramount+ miniseries of Stephen King''s The Stand.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (502, 'Zack Newick', NULL, '\x6e756c6c', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (464, 'Jonah Hill', '1983-12-20', '\', 'Jonah Hill Feldstein (born December 20, 1983) is an American actor, comedian, screenwriter, producer and director. He is known for his comedic roles in films including Superbad (2007), Knocked Up (2007), 21 Jump Street (2012), This Is the End (2013), and 22 Jump Street (2014). For his performances in Moneyball (2011) and The Wolf of Wall Street (2013), he was nominated for the Academy Award for Best Supporting Actor.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (465, 'Margot Robbie', '1990-07-02', '\', 'Margot Elise Robbie (born July 2, 1990) is an Australian actress and producer. Known for her work in both blockbuster and independent films, she has received several accolades, including nominations for two Academy Awards, four Golden Globe Awards, and five British Academy Film Awards. Time magazine named her one of the 100 most influential people in the world in 2017 and she was ranked as one of the world''s highest-paid actresses by Forbes in 2019.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (466, 'Kyle Chandler', '1965-09-17', '\', 'Kyle Martin Chandler (born September 17, 1965) is an American film and television actor best known for his roles as Gary Hobson on CBS''s Early Edition and Eric Taylor on the series Friday Night Lights, as well as Bill Hurley on Showtime''s Super Pumped, Colonel Cathcart on Hulu''s Catch-22, Brooks Davis in Game Night, Joe Chandler in Manchester by the Sea, John Rayburn in Netflix''s Bloodline, FBI Agent Patrick Denham in The Wolf of Wall Street, Tommy Keely in The Spectacular Now, Paul Andrews in Broken City, Joseph Bradley in Zero Dark Thirty, Hamilton Jordan in Argo, Jackson Lamb in Super 8, John Driscoll in The Day the Earth Stood Still (2008), Francis Manner in The Kingdom (2007), Bruce Baxter in King Kong (2005), Grant Rashton on NBC''s The Lyon''s Den, Jake Evans on ABC''s What About Joan?, Captain in Mulholland Falls, Buddy Jackson in Pure Country, Jeff Metcalf on ABC''s Homefront, Private William Griner on CBS''s Tour of Duty, and Charles Main on ABC''s miniseries North and South.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (489, 'J.C. Currais', '1984-10-04', '\', 'JC''s high energy performance and edgy comedy only accentuate his larger than life persona, he''s a crowd favorite! Years of hard work have paid off for JC who makes a living as a comedian - but he wants more, he wants to make it to the big time! With a stellar management team in his corner, JC landed Conan and numerous comedy show cameos but to really climb that next rung on the ladder ... JC has to make it into JFL.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (468, 'Rob Reiner', '1947-03-06', '\', 'Robert Norman Reiner (born March 6, 1947) is an American actor and filmmaker. As an actor, Reiner first came to national prominence with the role of Michael "Meathead" Stivic on the CBS sitcom All in the Family (1971–1979), a performance that earned him two Primetime Emmy Awards.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (343, 'John David Washington', '1984-07-28', '\', 'John David Washington (born July 28, 1984) is an American actor and former American football running back. He shifted to an acting career like his father, Denzel Washington and mother, Pauletta Washington. In 2015, he started with the HBO comedy series Ballers and his role in BlacKkKlansman (2018) brought him a Golden Globe nomination for Best Actor. After seeing Washington''s work in BlacKkKlansman, well-renowned director Christopher Nolan hand-picked him to anchor his thriller film Tenet (2020). Since then, Washington has also starred in Malcolm & Marie (2021), Amsterdam (2022) and The Creator (2023).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (344, 'Robert Pattinson', '1986-05-13', '\', 'Robert Douglas Thomas Pattinson (born 13 May 1986) is an English actor. Noted for his versatile roles in both big-budget and independent films, Pattinson has been ranked among the world''s highest-paid actors. After starting to act in a London theatre club at age 15, Pattinson began his film career by playing Cedric Diggory in the fantasy film Harry Potter and the Goblet of Fire (2005). He gained worldwide recognition for portraying Edward Cullen in The Twilight Saga film series (2008–2012), which grossed over $3.3 billion worldwide. After starring in the romantic dramas Remember Me (2010) and Water for Elephants (2011), Pattinson received critical acclaim for his performances in independent films from auteur directors. He starred in David Cronenberg''s thriller Cosmopolis (2012), David Michôd''s dystopian western The Rover (2014), James Gray''s adventure drama The Lost City of Z (2016), the Safdie Brothers'' crime drama Good Time (2017), Claire Denis'' science-fiction drama High Life (2018), and Robert Eggers'' psychological horror film The Lighthouse (2019). He returned to mainstream films with a leading role in Christopher Nolan''s spy film Tenet (2020), and starred as the DC Comics superhero Batman in Matt Reeves'' film The Batman (2022).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (345, 'Elizabeth Debicki', '1990-08-24', '\', 'Elizabeth Debicki (born 24 August 1990) is an Australian actress. After making her feature film debut in A Few Best Men (2011), she appeared in The Great Gatsby (2013) as Jordan Baker. Other roles are in the limited series The Night Manager (2016) and Widows (2018).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (346, 'Kenneth Branagh', '1960-12-10', '\', 'Sir Kenneth Charles Branagh (born 10 December 1960) is a British actor and filmmaker. Branagh trained at the Royal Academy of Dramatic Art in London; in 2015 he succeeded Richard Attenborough as its president. He has been nominated for five Academy Awards and five Golden Globe Awards. He has won three BAFTAs and two Emmy Awards. He was appointed a Knight Bachelor in the 2012 Birthday Honours and knighted on 9 November 2012.  He was made a Freeman of his native city of Belfast in January 2018. In 2020, he was listed at number 20 on The Irish Times list of Ireland''s greatest film actors.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (347, 'Dimple Kapadia', '1957-06-08', '\', 'Dimple Kapadia (born 8 June 1957) is an Indian film actress who predominantly appears in Hindi films. She was launched by Raj Kapoor at age 16, playing the title role in his teen romance Bobby (1973). In that same year she married Indian actor Rajesh Khanna and retired from acting. Kapadia returned to the film industry in 1984, following her separation from Khanna. One of her films of that period was the drama Saagar (1985). Both Bobby and Saagar won her the Filmfare Award for Best Actress. She went on to establish herself as one of the leading actresses of Hindi cinema in the 1980s.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (348, 'Himesh Patel', '1990-10-30', '\', 'Himesh Patel was born on October 13, 1990 in Huntingdon, Cambridgeshire, England as Himesh Jitendra Patel. He is an actor and writer, known for EastEnders: E20 (2010), My Pure Land (2017) and EastEnders (1985).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (349, 'Aaron Taylor-Johnson', '1990-06-13', '\', 'Aaron Perry Taylor-Johnson (né Johnson; born 13 June 1990) is an English actor. He is best known for his portrayal of the title character in Kick-Ass (2010) and its 2013 sequel, and the Marvel Cinematic Universe (MCU) character Pietro Maximoff in Captain America: The Winter Soldier (2014) and Avengers: Age of Ultron (2015). Taylor-Johnson began performing at age six and has appeared in such films as Shanghai Knights (2003), The Illusionist (2006), The Thief Lord (2006), and Angus, Thongs and Perfect Snogging (2008).
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (469, 'Jon Bernthal', '1976-09-20', '\', 'Jonathan Edward Bernthal (born September 20, 1976) is an American actor.  Beginning his career in the early 2000s, he came to prominence for portraying Shane Walsh on the AMC horror series The Walking Dead (2010–2012; 2018), where he was a starring cast member in the first two seasons. Bernthal achieved further recognition as Frank Castle / The Punisher in the Marvel Cinematic Universe (MCU) television series Daredevil and The Punisher, a role he will reprise in Daredevil: Born Again. His film roles include Snitch (2013), The Wolf of Wall Street (2013), Fury (2014), Sicario (2015), The Accountant (2016), Baby Driver (2017), Wind River (2017), Widows (2018), Ford v Ferrari (2019); Those Who Wish Me Dead, King Richard, and The Many Saints of Newark (all 2021).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (351, 'Clémence Poésy', '1982-10-30', '\', 'Clémence Guichard (born 30 October 1982), known professionally as Clémence Poésy, is a French actress and fashion model. After starting on the stage as a child, Poésy studied drama and has been active in both film and television since 1999, including some English-language productions. She is known for the roles of Fleur Delacour in the Harry Potter film series, Chloë in In Bruges, Rana in 127 Hours, Natasha Rostova in War and Peace, and the lead role as Elise Wassermann in the 24-episode series The Tunnel.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (352, 'Martin Donovan', '1957-08-19', '\', 'Martin Donovan (born August 19, 1957) is an American stage and film actor. He has had a long collaboration with the director Hal Hartley, appearing in many of his films, including Trust (1990), Surviving Desire (1991), Simple Men (1992), Flirt (1993), Amateur (1994), and The Book of Life (1998) (in which he played Jesus). He is best known as Peter Scottson, the DEA agent on Showtime''s Weeds. He made his Writing and Directorial debut in 2011 with the film Collaborator, which he stars in with David Morse.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (353, 'Yuri Kolokolnikov', '1980-12-15', '\', 'Yuri Andreyevich Kolokolnikov (born December 15, 1980) is a Russian actor of theatre and cinema. In the West, Kolokolnikov is best known for his performance as Styr in the television series Game of Thrones and as Gennadi Bystrov in The Americans.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (354, 'Anthony Molinari', '1974-05-09', '\', 'From Wikipedia, the free encyclopedia
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (355, 'Laurie Shepherd', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (356, 'Fiona Dourif', '1981-10-30', '\', 'Fiona Dourif (born October 30, 1981) is an American actress and producer. She is mostly known for her role as Nica Pierce in the Child''s Play movies and the Chucky TV series. She is also known for her role as Bart Curlish in BBC America''s Dirk Gently''s Holistic Detective Agency and as the young Diane Jones in Dustin Lance Black''s When We Rise. She has appeared in Showtime''s Shameless and in a recurring role on NBC''s The Blacklist.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (357, 'Juhan Ulfsak', '1973-04-18', '\', 'Juhan Ulfsak (born April 18, 1973 in Tallinn) is an Estonian actor.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (358, 'Jefferson Hall', '1977-12-06', '\', 'Jefferson Hall (born 6 December 1977) is an English actor. He has played the roles of Hugh of the Vale in Game of Thrones, Varg in Wizards vs Aliens on CBBC, Torstein in Vikings and as Aaron Korey in Halloween. He was credited as Robert Hall in his earlier roles. In 2022, he was cast as twins Jason Lannister and Tyland Lannister in the Game of Thrones prequel series, House of the Dragon.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (359, 'Ivo Uukkivi', '1965-10-11', '\', 'Ivo Uukkivi (born October 11, 1965 in Tallinn) is an Estonian stage, film, radio, and television actor, television producer and, under the nickname Munk, founder of and singer with the punk band Velikije Luki. He was born in Tallinn and was one of two siblings
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (360, 'Andrew Howard', '1969-06-12', '\', 'Andrew Howard is a Welsh theatre, television and film actor.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (490, 'Jimmy Ortega', '1957-11-18', '\', 'He was born and raised in El Paso Texas. Miguel Ortega (father) was a cross country truck driver and Paulina Ortega (mother) a housewife. Began career doing summer stock theater for 2 years - El Paso Del Norte. Moved to Los Angeles in 1978. Shortly after arriving, he started to work as a stuntman on a picture by the name of Hooper (1978). His first acting job was in a guest starring role on a TV show by the name of CHiPs (1977). He has won a Stuntman''s Award - Most Spectacular Sequence - "North & South" miniseries. He also won a Screen Actors Guild Award - Outstanding Performance By Cast - Traffic (2000).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (491, 'Hansford Prince', NULL, '\', 'Hansford Prince is known for Copycat (1995), Babylon (2022) and Nash Bridges (1996).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (492, 'Telvin Griffin', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (361, 'Rich Ceraulo Ko', '1977-03-27', '\', 'Rich Ceraulo Ko was born on a US Air Force base in Bitburg, Germany. His father, Richard Loreto Ceraulo, was an Air Force Master Sergeant and his mother, Yang Cha Ko, a housekeeper, and homemaker. Growing up, his family hopped from base to base, eventually settling on Long Island, New York. Rich studied biology/pre-medicine at New York University before transferring to the Tisch School of the Arts his junior year where he studied with Doug Moston of the Actors Studio. After graduating, Rich appeared in the Broadway musical Flower Drum Song then quickly made his way out to Los Angeles to pursue a career in film and television.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (362, 'Jonathan Camp', NULL, '\', 'Jonathan Camp is an American film and television actor.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (363, 'Fionn Whitehead', '1997-07-18', '\', 'Fionn Whitehead (RP: fɪn) (born July 18, 1997) is an English actor, known for playing the lead role in the 2017 film Dunkirk. Whitehead''s acting was first credited in the 2016 ITV miniseries Him.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (470, 'Jon Favreau', '1966-10-19', '\', 'Jonathan Kolia Favreau (/ˈfævroʊ/; born October 19, 1966) is an American actor, director, producer and screenwriter.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (365, 'Mark Rylance', '1960-01-18', '\', 'Sir David Mark Rylance Waters (born 18 January 1960 in Ashford, Kent, England) is an English actor, theatre director, and playwright.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (471, 'Jean Dujardin', '1972-06-19', '\', 'Jean Edmond Dujardin (born 19 June 1972) is a French actor and comedian. He began his career as a stand-up comedian in Paris before guest starring in comedic television programmes and films. He first came to prominence with the cult TV series Un gars, une fille, in which he starred alongside his partner Alexandra Lamy, before gaining success in film with movies such as Brice de Nice, Michel Hazanavicius''s OSS 117: Cairo, Nest of Spies and its sequel OSS 117: Lost in Rio, as well as 99 Francs.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (493, 'Olivia Wilde', '1984-03-10', '\', 'Olivia Jane Cockburn (born March 10, 1984), known professionally as Olivia Wilde, is an American actress and filmmaker. She played Remy "Thirteen" Hadley on the medical-drama television series House (2007–2012), and has appeared in the films Tron: Legacy (2010), Cowboys & Aliens (2011), The Incredible Burt Wonderstone (2013), and The Lazarus Effect (2015). Wilde made her Broadway debut in 2017, playing Julia in 1984. In 2019, she directed her first film, the teen comedy Booksmart, for which she won the Independent Spirit Award for Best First Feature. Wilde''s second feature as director, Don''t Worry Darling, was released in 2022.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (289, 'Johnathan Geare', NULL, '\x6e756c6c', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (290, 'Yuji Okumoto', '1959-04-20', '\', 'From Wikipedia, the free encyclopedia
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (291, 'Earl Cameron', '1917-08-18', '\', 'Earl Cameron was born on August 8, 1917 in Pembroke, Bermuda. He was an actor, known for Thunderball (1965), Inception (2010) and The Interpreter (2005). He was married to Barbara Cameron and Audrey J. P. Godowski. He died on July 3, 2020 in Kenilworth, Warwickshire, England.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (292, 'Ryan Hayward', NULL, '\x6e756c6c', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (494, 'Circus-Szalewski', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (379, 'Billy Howle', '1989-11-09', '\', 'Billy Howle was born in Stoke-on-Trent, England, to a schoolteacher mother and a father who teaches at Kent University, the second of four sons. His older brother, Sam, is a graphic designer. Despite his parents'' academic backgrounds, Billy has said that he was not interested in further education, and worked instead at the local Stephen Joseph theater, in community-based projects involving dance and acting. After a year at drama school, he enrolled at the prestigious Bristol Old Vic Theatre School, graduating in 2013. Having appeared at Bristol in ''The Little Mermaid,'' his next stage appearance was in New York at the Brooklyn Academy of Music, opposite Lesley Manville in Richard Eyre''s production of Henrik Ibsen''s ''Ghosts'' and a year later was reunited with Bristol Old Vic, the director, and Ms. Manville in a scorching production of ''Long Day''s Journey Into Night'' alongside Jeremy Irons - another Bristol Old Vic alumnus - Hadley Fraser, and Jessica Regan, more than holding his own with his older, more experienced co-stars. After a couple of small roles in television drama, Billy''s first substantial lead came in the youth-oriented murder mystery Glue (2014) in 2014, opening the first scene in memorable style as he rolled nude down stacks of grain in a barn. In 2016, he was in another murder mystery, The Witness for the Prosecution (2016), as the defendant accused of killing his wealthy benefactress, by which time he had filmed his first forays into cinema: On Chesil Beach (2017) and Anton Chekhov''s The Seagull (2018), both with Saoirse Ronan, and The Sense of an Ending (2017).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (380, 'Mikey Collins', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (381, 'Callum Blake', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (382, 'Dean Ridge', NULL, '\', 'Dean Ridge is known for Vikings (2013), Dunkirk (2017) and Knightfall (2017).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (383, 'Matthew McConaughey', '1969-11-04', '\', 'Matthew David McConaughey (born November 4, 1969) is an American actor. He first gained notice for his supporting performance in the coming-of-age comedy Dazed and Confused (1993), which was considered by many to be his breakout role. After a number of supporting roles in films including Angels in the Outfield (1994) and Texas Chainsaw Massacre: The Next Generation (1994), his breakthrough performance as a leading man came in the legal drama A Time to Kill (1996). He followed this with leading performances in the science fiction film Contact (1997), the historical drama Amistad (1997), the comedy-drama The Newton Boys (1998), the satire EDtv (1999), the war film U-571 (2000), and the psychological thriller Frailty (2001).
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (384, 'Anne Hathaway', '1982-11-12', '\', 'Anne Jacqueline Hathaway (born November 12, 1982) is an American actress. She is the recipient of various accolades, including an Academy Award, a Golden Globe Award, and a Primetime Emmy Award, and was among the world''s highest-paid actresses in 2015. Her films have grossed over $6.8 billion worldwide, and she appeared on the Forbes Celebrity 100 list in 2009.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (385, 'Jessica Chastain', '1977-03-24', '\', 'Jessica Michelle Chastain (born March 24, 1977) is an American actress and film producer. Known for her roles in films with feminist themes, she has received various accolades, including an Academy Award, a Golden Globe Award, in addition to nominations for two British Academy Film Awards. Time magazine named her one of the 100 most influential people in the world in 2012.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (496, 'Li Jun Li', '1983-11-06', '\', 'Li Jun Li is an actress, known for her portrayal Lady Fay Zhu in Babylon, Iris Chang in the ABC series Quantico, Rose Cooper in the Fox series The Exorcist, and Jenny Wah in the Netflix series Wu Assassins.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (497, 'Kaia Gerber', '2001-09-03', '\', 'Kaia Jordan Gerber is an American fashion model and actress, signed with IMG Models. Kaia is the daughter of model-turned-businessman Rande Gerber and the supermodel Cindy Crawford.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (472, 'Joanna Lumley', '1946-05-01', '\', 'Dame Joanna Lamond Lumley DBE FRGS (born 1 May 1946) is a British actress, presenter, former model, author, television producer, and activist. She has won two BAFTA TV Awards for her role as Patsy Stone in the BBC sitcom Absolutely Fabulous (1992–2012), and was nominated for the 2011 Tony Award for Best Featured Actress in a Play for the Broadway revival of La Bête. In 2013, she received the Special Recognition Award at the National Television Awards, and in 2017 she was honoured with the BAFTA Fellowship award.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (387, 'Bill Irwin', '1950-04-11', '\', 'William Mills Irwin (born April 11, 1950) is an American actor, clown, and comedian. He began as a vaudeville-style stage performer and has been noted for his contribution to the renaissance of American circus during the 1970s. He has also made a number of appearances on film and television, and he won a Tony Award for his role in Who''s Afraid of Virginia Woolf on Broadway. He is also known as Mr. Noodle on the Sesame Street segment Elmo''s World, has appeared in the Sesame Street film short Does Air Move Things?, and regularly appeared as a therapist on Law & Order: Special Victims Unit.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (388, 'Ellen Burstyn', '1932-12-07', '\', 'Ellen Burstyn (born Edna Rae Gillooly; December 7, 1932) is an American actress. Known for her portrayal of complicated women in dramas, Burstyn was the recipient of various accolades, and was among the few performers to have won an Oscar, Emmy, and Tony (Triple Crown of Acting).
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (389, 'Mackenzie Foy', '2000-11-10', '\', 'Mackenzie Christine Foy (born November 10, 2000) is an American actress and model. She is known for portraying Renesmee Cullen in the 2012 film The Twilight Saga: Breaking Dawn – Part 2, which earned her a Young Artist Award nomination as Best Supporting Young Actress in a Feature Film. She portrayed young Murphy in the 2014 space epic Interstellar, for which she received a Saturn Award for Best Performance by a Younger Actor among other awards nominations. She starred as Clara in Disney''s 2018 film The Nutcracker and the Four Realms.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (390, 'Casey Affleck', '1975-08-12', '\', 'Caleb Casey McGuire Affleck-Boldt (born August 12, 1975) is an American actor and filmmaker. He is the recipient of various accolades, including an Academy Award, a British Academy Film Award, a Golden Globe Award and a Satellite Award. He began his career as a child actor, appearing in the PBS television film Lemon Sky (1988) and the miniseries The Kennedys of Massachusetts (1990). He later appeared in three Gus Van Sant films: To Die For (1995), Good Will Hunting (1997), and Gerry (2002), and in Steven Soderbergh''s comedy heist trilogy Ocean''s Eleven (2001), Ocean''s Twelve (2004), and Ocean''s Thirteen (2007). His first leading role was in Steve Buscemi''s independent comedy-drama Lonesome Jim (2006).
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (391, 'John Lithgow', '1945-10-19', '\', 'John Arthur Lithgow (born October 19, 1945) is an American actor. Prolific in films, television and on stage, Lithgow is the recipient of numerous accolades, including two Golden Globe Awards, six Primetime Emmy Awards, three Screen Actors Guild Awards, two Tony Awards and nominations for two Academy Awards and four Grammy Awards. He was inducted into the American Theater Hall of Fame and has received a star on the Hollywood Walk of Fame.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (392, 'Wes Bentley', '1978-09-04', '\', 'Wesley Cook "Wes" Bentley (born September 4, 1978) is an American film actor known for his roles as Ricky Fitts in American Beauty (1999) and Seneca Crane in The Hunger Games (2012). Bentley was one of four subjects in the documentary My Big Break (2009), which covered his fame after American Beauty and struggles with substance abuse. Rebuilding his career, he starred in the premier of Venus in Fur by David Ives in the off-Broadway production in 2010, whose run was extended.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (393, 'David Gyasi', '1980-01-02', '\', 'A British actor. He is best known for his roles in Cloud Atlas (2012) and Interstellar (2014), as well as the lead role of Lex Carnahan in The CW miniseries Containment.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (398, 'William Devane', '1939-09-05', '\', 'William Joseph Devane (born September 5, 1937) is an American film, television and theater actor,  known for his role as Greg Sumner on the primetime soap opera Knots Landing and as James Heller on the Fox serial drama 24, the role he reprised in Live Another Day. He is also known for his supporting roles in films such as McCabe & Mrs. Miller,  Family Plot), Marathon Man, Rolling Thunder and Space Cowboys.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (399, 'Josh Stewart', '1977-02-06', '\', 'Joshua Regnall Stewart (born February 6, 1977) is an American actor best known for his role as Holt McLaren in the FX TV series Dirt. He was also cast as Brendan Finney in the final season of the NBC TV series Third Watch.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (400, 'Collette Wolfe', '1980-04-04', '\', 'Collette Wolfe is an American actress, known for her roles in Observe and Report (2009), Hot Tub Time Machine (2010) and its'' sequel Hot Tub Time Machine 2 (2015), Young Adult (2011), and Interstellar (2014).  She also appeared in Semi-Pro, Four Christmases, and 17 Again.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (401, 'Leah Cairns', '1974-06-02', '\', 'Leah Cairns is a Canadian actress. She is best known for her role as Lieutenant Margaret "Racetrack" Edmondson in Battlestar Galactica.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (402, 'Russ Fega', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (473, 'Cristin Milioti', '1985-08-16', '\', 'Cristin Milioti (born August 16, 1985) is an American actress. She is known for playing Tracy McConnell in the CBS sitcom How I Met Your Mother from 2013 to 2014, and for her work in theater productions such as That Face, Stunning, and the Tony Award-winning musical Once, for which she won a Grammy Award and was nominated for a Tony Award. She has also played Teresa Petrillo Belfort in the 2013 film The Wolf of Wall Street, Sarah Wilder in the 2020 film Palm Springs, Betsy Solverson in the second season of Fargo (2015), Hazel Green in the HBO Max comedy series Made for Love (2021–2022), and Emma in the Peacock black comedy mystery series The Resort (2022-).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (474, 'Christine Ebersole', '1953-02-21', '\', 'Christine Ebersole won the 2007 Tony Award for Best Actress in a Musical for her work in "Grey Gardens". Previously, she was awarded the Drama Desk Award, the Outer Critics Circle Award, the Drama League awarded her both a citation and the Outstanding Performance of the Year, and she was named to its dais for 2007. She also received a special citation from the New York Drama Critics'' Circle and the Obie for her off-Broadway turn in "Grey Gardens".');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (476, 'Katarina Čas', '1976-09-23', '\', 'Katarina Cas was born on September 23, 1976 in Slovenj Gradec, Slovenia, Yugoslavia. Katarina is an actor and assistant director, known for The Wolf of Wall Street (2013), The Guard (2011) and Danny Collins (2015).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (477, 'P.J. Byrne', '1974-12-15', '\', 'Paul Jeffrey Byrne (born December 15, 1974) is an American film and television actor. He is best known for his roles as Nicky "Rugrat" Koskoff in the Martin Scorsese film The Wolf of Wall Street (2013) and Bolin on Nickelodeon''s animated series The Legend of Korra (2012–2014).
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (478, 'Kenneth Choi', '1971-10-20', '\', 'Kenneth Choi (born October 20, 1971) is an American actor. He is known for playing Henry Lin on the television series Sons of Anarchy (2008–2014), Chester Ming in Martin Scorsese''s The Wolf of Wall Street (2013), and Judge Lance Ito in The People v. O. J. Simpson: American Crime Story (2016). He is also known for his roles as Jim Morita and Principal Morita in the Marvel Cinematic Universe films Captain America: The First Avenger (2011) and Spider-Man: Homecoming (2017) respectively, and Lewis on the Fox comedy series The Last Man on Earth (2016–2017). Since 2018 he is starring in the Fox drama series 9-1-1, playing LAFD firefighter Howie "Chimney" Han.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (479, 'Brian Sacca', '1978-12-07', '\', 'Brian Sacca was an actor who had a successful Hollywood career. Sacca marked his early career with roles in "United States of Tara" (Showtime, 2008-2011) and "I''m Having a Difficult Time Killing My Parents" (2011). He went on to act in "Kroll Show" (Comedy Central, 2012-15) and the Leonardo DiCaprio smash hit crime drama "The Wolf of Wall Street" (2013).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (480, 'Henry Zebrowski', '1984-05-01', '\', 'Henry Thomas Zebrowski, Jr. (born May 1, 1984) is an American actor and comedian, known for his work on the Adult Swim series Your Pretty Face is Going to Hell, NBC series Heroes Reborn, and the podcast The Last Podcast on the Left.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (481, 'Ethan Suplee', '1976-05-25', '\', 'Ethan Suplee (born May 25, 1976) is an American film and television actor best known for his roles as Seth Ryan in American History X, Louie Lastik in Remember the Titans, Frankie in Boy Meets World, Randy Hickey in My Name Is Earl, Thumper in The Butterfly Effect, Dewey in Unstoppable, and his roles in Kevin Smith films.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (503, 'Franco Franchi', '1928-09-18', '\', 'From Wikipedia, the free encyclopedia
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (504, 'Saro Urzì', '1913-02-24', '\', 'Saro Urzì was born on February 24, 1913, died  November 2, 1979 (age 66) in San Giuseppe Vesuviano, Italy. He was an actor.');
