INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (508, 'Salvatore Puntillo', '1935-07-27', '\', 'Salvatore Puntillo was born on July 27, 1935 in Rende, Calabria, Italy. He is an actor, known for Deep Red (1975), Top Sensation (1969) and Marco Polo (1982).');
