INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (520, 'Salvatore Carrara', NULL, '\x6e756c6c', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (521, 'Chris Pratt', '1979-06-21', '\', 'Christopher Michael Pratt (born 21 June 1979) is an American actor, known for starring in both television and action films. He rose to prominence for his television roles, particularly in the NBC sitcom Parks and Recreation (2009–2015), for which he received critical acclaim and was nominated for the Critics'' Choice Television Award for Best Supporting Actor in a Comedy Series in 2013. He also starred earlier in his career as Bright Abbott in The WB drama series Everwood (2002–2006) and had roles in Wanted (2008), Jennifer''s Body (2009), Moneyball (2011), The Five-Year Engagement (2012), Zero Dark Thirty (2013), Delivery Man (2013), and Her (2013).
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (522, 'Jennifer Lawrence', '1990-08-14', '\', 'Jennifer Shrader Lawrence (born August 15, 1990) is an American actress. The world''s highest-paid actress in 2015 and 2016, her films have grossed over $6 billion worldwide to date. She appeared in Time''s 100 most influential people in the world list in 2013 and the Forbes Celebrity 100 list from 2013 to 2016.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (523, 'Michael Sheen', '1969-02-05', '\', 'Michael Christopher Sheen (born 5 February 1969) is a Welsh actor and political activist. After training at London''s Royal Academy of Dramatic Art (RADA), he worked mainly in theatre throughout the 1990s and made notable stage appearances in Romeo and Juliet (1992), Don''t Fool With Love (1993), Peer Gynt (1994), The Seagull (1995), The Homecoming (1997), and Henry V (1997). His performances in Amadeus at the Old Vic and Look Back in Anger at the National Theatre were nominated for Olivier Awards in 1998 and 1999, respectively. In 2003, he was nominated for a third Olivier Award for his performance in Caligula at the Donmar Warehouse.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (524, 'Laurence Fishburne', '1961-07-30', '\', 'Laurence John Fishburne III (born July 30, 1961) is an American actor and producer. He has been critically hailed for his forceful, militant, and authoritative characters in his films. He is known for playing Morpheus in the first three films of The Matrix series (1999–2003), Jason "Furious" Styles in the John Singleton drama film Boyz n the Hood (1991), Tyrone "Mr. Clean" Miller in Francis Ford Coppola''s war film Apocalypse Now (1979), and "The Bowery King" in the John Wick film series (2017–present).
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (525, 'Andy García', '1956-04-12', '\', 'Andy García (born Andrés Arturo García Menéndez, April 12, 1956) is a Cuban-American actor. He''s best known for his roles as Vincent Mancini in The Godfather III, George Stone in The Untouchables, Dr. Ramirez in Stand and Deliver, Raymond Avila in Internal Affairs, Michael Green in When a Man Loves a Woman, Frank Conner in Desperate Measures, Terry Benedict in the Ocean''s Trilogy, Andre Allen on HBO''s Ballers, Captain Norris in Passengers (2016), President Andrew Palma in Geostorm, Mitchel in Book Club 1 & 2, Ricardo Montalban in My Dinner with Hervé, Father Patrick in Words on Bathroom Walls, Billy Herrera in remake of Father of the Brida (2022), and Marsh in Expend4bles.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (526, 'Vince Foster', NULL, '\', 'Vince Foster is known for Godzilla: King of the Monsters (2019), The Resident (2018) and The Walking Dead (2010).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (527, 'Kara Flowers', '1984-12-28', '\', 'Born and raised in Lyons, Kansas, growing up an athlete, an artist, and a serious tomboy. Her favorite childhood memories come from summering at Lake Wilson with her family. Her mother and father are both Kansas natives. Kara discovered performance art after watching the movie SLAM, starring poet Saul Williams and started writing and performing poetry at the age of 13. She gave up sports to spent her high school career as a Debate and Speech & Drama (Forensics) competitor. Earning five State titles, and two National Semi-Finalist titles (National Forensic League), she attended Kansas State University and continued to compete with the Collegiate Speech Team. Her most important mentor as a youth, was her high school debate coach, Mr. Troyer. Kara moved to Atlanta, Georgia in 2006, and attended law school in 2010. Kara works as a film, television, and commercial actor, a model, and spokesperson.  - IMDb Mini Biography By: Kara');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (528, 'Conor Brophy', NULL, '\', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (529, 'Julee Cerda', '1978-01-29', '\', 'Julee Cerda is an American actress born in Seoul, South Korea. She was raised in New York and spent part of her childhood in father''s country in the Dominican Republic. She speaks fluent Spanish. She attended Marist College in Poughkeepsie, NY and currently resides in New York City. She is known for The Intern (2015), The Disappearance of Eleanor Rigby: Them (2014), and A Miracle in Spanish Harlem (2013).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (530, 'Aurora Perrineau', '1994-09-23', '\', 'Aurora Perrineau (born September 23, 1994) is an American actress and model.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (531, 'Lauren Farmer', NULL, '\x6e756c6c', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (532, 'Emerald Mayne', NULL, '\x6e756c6c', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (533, 'Kristin Brock', NULL, '\', 'Kristin Brock is known for Passengers (2016), The Dirt (2019) and Stargirl (2020).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (534, 'Tom Ferrari', NULL, '\x6e756c6c', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (535, 'Quansae Rutledge', NULL, '\x6e756c6c', 'Quansae Rutledge is known for Passengers (2016).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (536, 'Desmond Reid', NULL, '\x6e756c6c', '');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (537, 'Emma Clarke', '1986-10-23', '\', 'Emilia Isobel Euphemia Rose Clarke MBE (born 23 October 1986) is a British actress. She is best known for her portrayal of Daenerys Targaryen in the HBO fantasy series Game of Thrones (2011–2019), for which she received nominations for four Primetime Emmy Awards. She is also known for her role in the Star Wars film Solo: A Star Wars Story (2018) and the romantic dramas Me Before You (2016) and Last Christmas (2019).');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (538, 'Chris Edgerly', '1969-08-06', '\', 'Edgerly was born in Silver Spring, Maryland and moved at the age of 2 with his mom and two brothers to Savannah, Georgia.
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (539, 'Fred Melamed', '1956-05-13', '\', 'Fred Melamed (born May 13, 1956 in New York City) is an American actor and writer. He received his theatrical training at Hampshire College and the Yale School of Drama. At Yale, he was a Samuel F. B. Morse College Graduate Fellow. He was also a nominee for the Irene Ryan Award, a prize conferred upon the most promising young actors in the United States. While still at Yale, he was an instructor at the well-known performing arts camp, Stagedoor Manor.');
INSERT INTO tweb.actors (id, name, date_birth, image, description) OVERRIDING SYSTEM VALUE VALUES (540, 'Matt Corboy', '1973-06-04', '\', '');
