INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (3, 'Hans Zimmer', '1957-09-12', 'Hans Florian Zimmer (born September 12th, 1957) is a German composer and record producer. Since the 1980s, he has composed music for over 150 films. His works include The Lion King, for which he won Academy Award for Best Original Score in 1994, the Pirates of the Caribbean series, The Thin Red Line, Gladiator, The Last Samurai, The Dark Knight Trilogy, Inception, and Interstellar. Zimmer spent the early part of his career in the United Kingdom before moving to the United States. He is the head of the film music division at DreamWorks studios and works with other composers through the company that he founded, Remote Control Productions.  Zimmer''s works are notable for integrating electronic music sounds with traditional orchestral arrangements. He has received fourGrammy Awards, three Classical BRIT Awards, two Golden Globes, and an Academy Award. He was also named on the list of Top 100 Living Geniuses, published by The Daily Telegraph.', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (77, 'Lee Smith', '1960-06-10', 'Lee Smith was born in Sydney, New South Wales, Australia. He was nominated for the Academy Award for Best Film Editing for Master and Commander: The Far Side of the World (2004) and The Dark Knight (2008). He was also nominated for the BAFTA Award for Best Editing for The Dark Knight and for Inception (2010). He was nominated for the BAFTA Award for Best Sound for The Piano (1993). He began his career as a sound editor/sound designer for films such as Dead Calm (1989), The Piano (1993) (for which he was nominated for the BAFTA Award for Best Sound), The Portrait of a Lady (1996), and Holy Smoke! (1999). Smith was also editing films during this interval; he was one of the editors for RoboCop 2 (1990).
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (148, 'Rodrigo Prieto', '1965-11-23', 'Rodrigo Prieto Stambaugh, ASC, AMC (born November 23, 1965), is a Mexican cinematographer. He has collaborated with Martin Scorsese and Alejandro González Iñárritu, among other prominent directors. He is a member of both the Mexican Society of Cinematographers and the American Society of Cinematographers. Throughout his career, Prieto has received many awards and nominations, including three Academy Award nominations for Best Cinematography in Ang Lee''s Brokeback Mountain (2005), Martin Scorsese''s Silence (2016), and The Irishman (2019).', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (16, 'Christopher Nolan', '1970-07-30', 'Christopher Edward Nolan, CBE (born 30 July 1970) is a British-American film director, screenwriter, and producer. He was born in Westminster, London, England and holds both British and American citizenship due to his American mother. He is known for writing and directing critically acclaimed films such as Memento (2000), The Prestige (2006), The Dark Knight Trilogy (2005-12), Inception (2010), Interstellar (2014) and Dunkirk (2017). Nolan is the founder of the production company Syncopy Films. He often collaborates with his wife, producer Emma Thomas, and his brother, screenwriter Jonathan Nolan.', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (19, 'Emma Thomas', '1971-12-09', 'Emma Thomas (born 9 December 1971) is a British film producer, known for co-producing films such as The Prestige (2006), Inception (2010), The Dark Knight Trilogy (2005–2012), Interstellar (2014), Dunkirk (2017) and Tenet (2020). She frequently collaborates with her husband, filmmaker Christopher Nolan.', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (20, 'Wally Pfister', '1961-07-08', 'Walter C. Pfister (born July 8, 1961) is an American director and former cinematographer, who is best known for his work with filmmaker Christopher Nolan. Some of his collaborations with Nolan include Memento (2000), The Dark Knight Trilogy (2005–2012), and Inception (2010). For his work on Inception, Pfister won an Academy Award for Best Cinematography and received a BAFTA Award nomination.
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (86, 'John Bernard', NULL, '', '\x6e756c6c');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (158, 'Francine Maisler', '1961-08-04', 'Francine Maisler is a casting director and producer, known for 12 Years a Slave (2013), The Revenant (2015) and Birdman or (The Unexpected Virtue of Ignorance) (2014).', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (87, 'Hélène Cardona', NULL, 'Hélène Cardona is a poet, linguist, literary translator and actor. She was born in Paris, the daughter of Spanish poet Jose Manuel Cardona, from Ibiza, and a Greek mother. She is a citizen of the United States, France and Spain.
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (94, 'Jeffrey Kurland', '1952-03-10', 'Jeffrey Kurland is an American costume designer. He was nominated for an Academy Award in the category Best Costume Design for the film Bullets Over Broadway. Kurland was also honored the Costume Designers Guild for the Career Achievement Award.
