INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (60, 'Jonathan Nolan', '1976-06-06', 'Jonathan Nolan (born 6 June 1976) is a British-American screenwriter, television producer, director, and author. He is the creator of the CBS science fiction series Person of Interest (2011–2016) and co-creator of the HBO science fiction western series Westworld (2016–present).
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (126, 'Avi Arad', '1948-08-01', 'Avi Arad is an Israeli-American businessman. He became the CEO of the company Toy Biz in the 1990s, and soon afterward became the chief creative officer of Marvel Entertainment, a Marvel director, and the chairman, CEO, and founder of Marvel Studios.', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (127, 'Richard Pearson', '1961-11-03', '', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (130, 'Frank Miller', '1957-01-27', 'Frank Miller (born January 27, 1957) is an American comic book artist, writer and film director best known for his dark, film noir-style comic book stories and graphic novels Ronin, Daredevil: Born Again, Batman: The Dark Knight Returns, Sin City and 300. He also directed the film version of The Spirit, shared directing duties with Robert Rodriguez on Sin City and produced the film 300.
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (131, 'Bob Kane', '1915-10-24', 'Bob Kane (born Robert Kahn; October 24, 1915 – November 3, 1998) was an American comic book artist and writer, credited as the creator of the DC Comics superhero Batman. He was inducted into both the comic book industry''s Jack Kirby Hall of Fame in 1994 and the Will Eisner Comic Book Hall of Fame in 1996.
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (132, 'Mark Friedberg', NULL, 'Mark Friedberg is an American production designer and second unit director based in New York City. He is known for frequently working with directors such as Wes Anderson, Jim Jarmusch, Barry Jenkins, Darren Aronofsky, and Todd Haynes.', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (133, 'Lawrence Sher', '1970-02-04', '', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (135, 'Laura Ballinger', NULL, '', '\x6e756c6c');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (136, 'Michael Uslan', '1952-06-02', 'Michael E. Uslan was born on December 15, 1950 in Cedar Grove, New Jersey, USA as Michael Elliot Uslan. He is a producer and writer, known for Batman Begins (2005), Batman: Mask of the Phantasm (1993) and National Treasure (2004).', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (137, 'Lisa Dennis', NULL, '', '\x6e756c6c');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (64, 'Chris Lebenzon', '1953-10-29', 'Christopher John "Chris" Lebenzon (born October 29, 1960) is an American film editor with more than 36 film credits dating from 1976. The films he has edited have grossed over 9 billion dollars worldwide.
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (138, 'Joel Silver', '1952-07-14', 'Joel Silver (born July 14, 1952) is an American film producer, known for action films like Lethal Weapon and Die Hard. He is owner of Silver Pictures and co-founder of Dark Castle Entertainment.
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (66, 'Manfred Banach', '1955-07-26', '', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (67, 'Frank Noack', NULL, '', '\x6e756c6c');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (68, 'Scott Silver', '1964-11-30', 'Scott Silver is a screenwriter and director.', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (69, 'Bruce Berman', '1952-04-25', 'Bruce Berman (born April 25, 1952) is an American film industry executive and executive producer. He is the chairman and CEO of Village Roadshow Pictures, a position he held from 1997 to 2021. His credits as an executive producer include American Sniper, The Lego Movie, The Great Gatsby, the Ocean''s trilogy, Sherlock Holmes and its sequel, Sherlock Holmes: A Game of Shadows, Happy Feet and The Matrix franchise.
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (139, 'Shane Black', '1961-12-16', 'Shane Black (born December 16, 1961) is an American film director, producer, screenwriter and actor who has written such films as Lethal Weapon and Lethal Weapon 2, The Monster Squad, The Last Boy Scout, Last Action Hero and The Long Kiss Goodnight. As an actor, Black is best known for his role as Rick Hawkins in Predator (1987).
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (141, 'Philippe Rousselot', '1945-09-04', '', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (142, 'Sala Baker', '1976-09-22', 'Sala Baker is an actor and stuntman from Wellington, New Zealand. Originally hired as one of several stunt performers for The Lord of the Rings film trilogy, he ended up landing the part of the Dark Lord Sauron. In addition, he also played several Orcs, a Gondorian, and one of the Rohirrim. Outside of the trilogy, Baker has performed in The Chronicles of Narnia: The Lion, the Witch and the Wardrobe and two Pirates of the Caribbean movies. Baker was also a part of the miscellaneous crew in the making of The Last Samurai in 2003.', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (144, 'Sarah Halley Finn', NULL, 'Sarah Halley Finn is an American casting director.
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (145, 'Richard Bridgland', NULL, '', '\x6e756c6c');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (146, 'Kym Barrett', '1977-01-11', 'Kym Barrett (born 11 August 1965) is an Australian costume designer of Hollywood films. She is a regular collaborator with The Wachowskis and was the costume designer of their films The Matrix, The Matrix Reloaded, The Matrix Revolutions, Speed Racer, Cloud Atlas and Jupiter Ascending.', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (147, 'John Ottman', '1964-07-06', 'From Wikipedia, the free encyclopedia
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (149, 'Martin Scorsese', '1942-11-17', 'Martin Charles Scorsese (born November 17, 1942) is an American film director, producer, screenwriter, and actor. One of the major figures of the New Hollywood era, he is widely regarded as one of the greatest and most influential directors in film history. Scorsese''s body of work explores themes such as Italian-American identity, Catholic concepts of guilt and redemption, faith, machismo, nihilism, crime and sectarianism. Many of his films are known for their depiction of violence and the liberal use of profanity. Scorsese has also dedicated his life to film preservation and film restoration by founding the nonprofit organization The Film Foundation in 1990, as well as the World Cinema Foundation in 2007 and the African Film Heritage Project in 2017.
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (151, 'Eugene Gearty', NULL, '', '\x6e756c6c');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (152, 'Ted Griffin', '1970-12-21', 'Ted Griffin (born December 21, 1970) is an American screenwriter whose credits include Ravenous, Matchstick Men, and Ocean''s Eleven.', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (153, 'Ellen Lewis', NULL, '', '\x6e756c6c');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (154, 'Georgia Kacandes', NULL, '', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (155, 'Thelma Schoonmaker', '1940-01-03', 'Thelma Schoonmaker (born January 3, 1940) is an American film editor, best known for her collaboration over five decades with director Martin Scorsese. She is the recipient of numerous accolades, including three Academy Awards, two BAFTA Awards, and four ACE Eddie Awards. She has been honored with the British Film Institute Fellowship in 1997, the Golden Lion for Lifetime Achievement in 2014, and the BAFTA Fellowship in 2019.  started working with Scorsese on his debut feature film, Who''s That Knocking at My Door (1967), and has edited all of his films since Raging Bull (1980). She has received nine nominations for the Academy Award for Best Film Editing, winning three—for Raging Bull, The Aviator (2004), and The Departed (2006), both records. She has also been nominated eleven times for the BAFTA Award for Best Editing, winning for Raging Bull and Goodfellas (1990).', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (156, 'Martin Klebba', '1969-06-23', '​From Wikipedia, the free encyclopedia.  
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (157, 'Richard Stutsman', NULL, '', '\x6e756c6c');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (159, 'Tobey Maguire', '1975-06-27', 'Tobias Vincent Maguire (born June 27, 1975) is an American actor and film producer. He is best known for playing the title character from Sam Raimi''s Spider-Man trilogy (2002–2007), a role he later reprised in Spider-Man: No Way Home (2021).
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (160, 'Wyck Godfrey', NULL, '', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (161, 'Mary Zophres', '1964-03-23', 'Mary Zophres is an American costume designer who has worked in the film industry since 1994. She has been nominated for the Academy Award for Best Costume Design thrice for True Grit (2010), La La Land (2016), and The Ballad of Buster Scruggs (2018). She has also been nominated for the BAFTA Award for Best Costume Design four times for Catch Me If You Can (2002), True Grit, La La Land, and The Ballad of Buster Scruggs.', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (162, 'Marc Platt', '1957-04-14', 'Marc E. Platt (born April 14, 1957) is an American producer who has worked in film, theatre, and television. He has received numerous accolades including two Tony Awards, two Primetime Emmy Awards, as well as nominations for three Academy Awards.', '\');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (163, 'Chris Palermo', NULL, 'Chris has more than twenty years experience in all aspects of stunt work, specializing in vehicles.
