INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (178, 'Thomas Newman', '1955-10-20', 'Thomas Montgomery Newman (born October 20, 1955) is an American composer best known for his many film scores. In a career that has spanned over four decades, he has scored numerous classics including The Player, The Shawshank Redemption, Cinderella Man, American Beauty, The Green Mile, In the Bedroom, Angels in America, Finding Nemo, WALL-E, the James Bond films Skyfall, Spectre, and the war film 1917.
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (179, 'David Lazan', NULL, '', '\x6e756c6c');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (183, 'Gene Serdena', NULL, '', '\x6e756c6c');
INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (184, 'Jack Gill', '1955-03-19', 'Jack Gill has created some of the movie industries'' most memorable action sequences. He directed 2nd unit and/or was the stunt coordinator on blockbuster movies such as Bad Boys for Life (2020) Venom (2018) Jumanji (2017) Fate of the Furious(2017) Furious 7 (2015), Ride Along 2 (2016), Ride Along (2014), Fast Five (2011), The Hangover Part III (2013), Date Night (2010), Wild Hogs (2007), Austin Powers in Goldmember (2002), Showtime (2002), Money Train (1995) and many more. As a stuntman, he has jumped cars and motorcycles through walls of wood, glass and flame on Knight Rider (1982) and The Dukes of Hazzard (1979); he has taken falls from buildings as high as twelve stories, and jumped from exploding boats and mountain tops; he has flown through the air hanging from helicopter struts and streaked through the sky in the F-16 Fighter aircraft.
