INSERT INTO tweb.director (id, name, date_birth, description, image) OVERRIDING SYSTEM VALUE VALUES (187, 'Jany Temime', NULL, 'Jany Temime is a Dutch/French costume designer known for her work on Skyfall and on 6 of the Harry Potter movies.', '\');
INSERT INTO tweb.film (cod, name, ranking, public_release, cover, description) OVERRIDING SYSTEM VALUE VALUES (99, 'Passengers', 2.46, '2016-12-21', '\', 'A spacecraft traveling to a distant colony planet and transporting thousands of people has a malfunction in its sleep chambers. As a result, two passengers are awakened 90 years early.');
INSERT INTO tweb.film (cod, name, ranking, public_release, cover, description) OVERRIDING SYSTEM VALUE VALUES (37, 'Inception', 5, '2010-07-15', '\', 'Cobb, a skilled thief who commits corporate espionage by infiltrating the subconscious of his targets is offered a chance to regain his old life as payment for a task considered to be impossible: "inception", the implantation of another person''s idea into a target''s subconscious.');
INSERT INTO tweb.film (cod, name, ranking, public_release, cover, description) OVERRIDING SYSTEM VALUE VALUES (75, 'Tenet', 3.47, '2020-08-22', '\', 'Armed with only one word - Tenet - and fighting for the survival of the entire world, the Protagonist journeys through a twilight world of international espionage on a mission that will unfold in something beyond real time.');
INSERT INTO tweb.film (cod, name, ranking, public_release, cover, description) OVERRIDING SYSTEM VALUE VALUES (81, 'Dunkirk', 3.74, '2017-07-19', '\', 'The story of the miraculous evacuation of Allied soldiers from Belgium, Britain, Canada and France, who were cut off and surrounded by the German army from the beaches and harbour of Dunkirk between May 26th and June 4th 1940 during World War II.');
INSERT INTO tweb.film (cod, name, ranking, public_release, cover, description) OVERRIDING SYSTEM VALUE VALUES (82, 'Interstellar', 5, '2014-11-05', '\', 'The adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel and conquer the vast distances involved in an interstellar voyage.');
INSERT INTO tweb.film (cod, name, ranking, public_release, cover, description) OVERRIDING SYSTEM VALUE VALUES (83, 'Uncharted', 4.32, '2022-02-10', '\', 'A young street-smart, Nathan Drake and his wisecracking partner Victor “Sully” Sullivan embark on a dangerous pursuit of “the greatest treasure never found” while also tracking clues that may lead to Nathan’s long-lost brother.');
INSERT INTO tweb.film (cod, name, ranking, public_release, cover, description) OVERRIDING SYSTEM VALUE VALUES (84, 'Joker', 3.79, '2019-10-01', '\', 'During the 1980s, a failed stand-up comedian is driven insane and turns to a life of crime and chaos in Gotham City while becoming an infamous psychopathic crime figure.');
INSERT INTO tweb.film (cod, name, ranking, public_release, cover, description) OVERRIDING SYSTEM VALUE VALUES (95, 'The Nice Guys', 3.23, '2016-05-15', '\', 'A private eye investigates the apparent suicide of a fading porn star in 1970s Los Angeles and uncovers a conspiracy.');
INSERT INTO tweb.film (cod, name, ranking, public_release, cover, description) OVERRIDING SYSTEM VALUE VALUES (96, 'The Wolf of Wall Street', 4.69, '2013-12-25', '\', 'A New York stockbroker refuses to cooperate in a large securities fraud case involving corruption on Wall Street, corporate banking world and mob infiltration. Based on Jordan Belfort''s autobiography.');
INSERT INTO tweb.film (cod, name, ranking, public_release, cover, description) OVERRIDING SYSTEM VALUE VALUES (97, 'Babylon', 4.67, '2022-12-22', '\', 'A tale of outsized ambition and outrageous excess, tracing the rise and fall of multiple characters in an era of unbridled decadence and depravity during Hollywood''s transition from silent films to sound films in the late 1920s.');
INSERT INTO tweb.film (cod, name, ranking, public_release, cover, description) OVERRIDING SYSTEM VALUE VALUES (98, 'Il Figlioccio del padrino', 0.06, '1973-02-01', '\', 'A mafioso falls in love with his boss''s daughter. Since the girl has already been widowed four times her father takes good care that this does not happen again.');
